typedef int nslSoundId;
typedef int SSEventId;

template <class T>
class singleton_ptr
{
  T* p;
public:
  operator T*() const { return p; }
};

class singleton
{
protected:
  singleton() {}
  virtual ~singleton() {}
};

class os_developer_options : public singleton
{
public:
  enum flags_t
  {
    FLAG_NO_AUDIO = 21
  };

  bool is_flagged(flags_t flag) const { return flags[flag]; }
  static os_developer_options* inst() { return instance; }

private:
  static singleton_ptr<os_developer_options> instance;
  bool flags[64];
};

enum EventType
{
  SS_FE_UPDOWN = 25,
  SS_FE_ERROR = 28
};

class SoundScriptManager : public singleton
{
public:
  static SoundScriptManager* inst() { return instance; }
  void pause();
  void unpause();
  SSEventId playEvent(EventType type, void* entity = 0, float fadeInTime = 0);

private:
  static singleton_ptr<SoundScriptManager> instance;
};

class PanelFile
{
  int slide_state;
public:
  bool IsSliding() const { return slide_state == 1 || slide_state == 2; }
};

class FEMenuEntry;

class FEMenu
{
public:
  virtual ~FEMenu();
  virtual void OnUp(int c);

protected:
  char before_highlighted[76];
  FEMenuEntry* highlighted;
};

class FrontEnd
{
public:
  virtual ~FrontEnd();
  PanelFile panel;
};

class FEGraphicalMenu : public FEMenu, public FrontEnd
{
};

class FEMultiMenu : public FEGraphicalMenu
{
public:
  virtual void OnUp(int c);
};

class BeachFrontEnd : public FEMultiMenu
{
public:
  void OnUp(int c);

private:
  char before_goal_num[160];
  int goal_num[3];
  int on_challenge;
  char before_fe_return[64];
  FEMenuEntry* fe_return;
  char before_voice_over[16];
  int voiceOverStage;
  nslSoundId voiceOverSound;
  SSEventId voiceOverEvent;
  char before_modes[64];
  bool in_description_mode;
  bool in_bio_mode;
  char before_frontend[512];
  bool in_frontend;
  char before_ignore_controller[4];
  bool ignore_controller;
  bool bio_up_pressed;
  char before_bio_counter[2];
  float bio_counter;
  float bio_count_max;

  void SetOnChallenge(int chall);
};

extern bool dampened;
extern void nslStopSound(nslSoundId sound);

void BeachFrontEnd::OnUp(int c)
{
	if((ignore_controller || panel.IsSliding()) && !in_frontend) return;
	if(in_description_mode) return;
	if(in_bio_mode)
	{
//		beach_bio->OnUp(c);
		bio_up_pressed = true;
		bio_counter = bio_count_max;
		return;
	}

	dampened = false;
	if(!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
		nslStopSound(voiceOverSound);
		voiceOverStage = 0;
	if (!in_frontend)
		SoundScriptManager::inst()->unpause();

//	SoundScriptManager::inst()->playEvent(SS_FE_UPDOWN);
	bool on_beach = 
		highlighted != fe_return 
/*	Save/load no longer part of map screen.  (dc 07/01/02)
		&& highlighted != save_load
*/
	;
	if(on_beach)
	{
		if(goal_num[0] != 0 && (on_challenge == 1 || (on_challenge == 2 && goal_num[1] == 0)))
		{
			SetOnChallenge(0);
			SoundScriptManager::inst()->playEvent(SS_FE_UPDOWN);		
		}
		else if(on_challenge == 2 && goal_num[1] != 0)
		{
			SetOnChallenge(1);
			SoundScriptManager::inst()->playEvent(SS_FE_UPDOWN);		
		}
		else
			SoundScriptManager::inst()->playEvent(SS_FE_ERROR);		
	}
	else
	{
		FEMultiMenu::OnUp(c);
	}
	if (!in_frontend)
		SoundScriptManager::inst()->pause();

}
